INSERT INTO `v1_d38afd42bd7a5abbd9da005bd006aa9f38085a6fcda6eb9a912312bf39eefddb` VALUES (0, 6, 113511, "あなた様のため…必ずや\n忘れられない最高の夏休みを\nお贈りいたしますわ…", 0, 0, 0, 1, 1007001042, 11, 1007001);
