INSERT INTO `v1_d38afd42bd7a5abbd9da005bd006aa9f38085a6fcda6eb9a912312bf39eefddb` VALUES (0, 5, 113511, "静かな島で弟くんと暮らす…\nここは本当に天国だね。", 0, 0, 0, 1, 1007005040, 11, 1007005);
