INSERT INTO `v1_d38afd42bd7a5abbd9da005bd006aa9f38085a6fcda6eb9a912312bf39eefddb` VALUES (0, 7, 113511, "お姉ちゃんも弟くんの\n楽しそうな顔が見られて\nうれしかったよ！", 0, 0, 0, 1, 1007007023, 11, 1007007);
