INSERT INTO `v1_d38afd42bd7a5abbd9da005bd006aa9f38085a6fcda6eb9a912312bf39eefddb` VALUES (0, 6, 113411, "そもそも、あなた様からの\nボールを落とすなんて、絶対に\nあってはいけませんわ…", 0, 0, 0, 1, 1007007028, 11, 1007007);
